python3 -c "
from PIL import Image, ImageDraw, ImageFont
im = Image.open('mol_0050.png').convert('RGB')
d = ImageDraw.Draw(im)
try:
    font = ImageFont.truetype('DejaVuSans.ttf', 22)
except:
    font = None
w,h=im.size
for x in range(0,w,50):
    c=(255,0,0) if x%100==0 else (255,170,170)
    d.line([(x,0),(x,h)], fill=c, width=1)
    if x%100==0: d.text((x+2,2), str(x), fill=(255,0,0), font=font)
for y in range(0,h,50):
    c=(0,0,255) if y%100==0 else (170,170,255)
    d.line([(0,y),(w,y)], fill=c, width=1)
    if y%100==0: d.text((2,y+2), str(y), fill=(0,0,255), font=font)
im.crop((820, 360, 1430, 830)).resize((1220, 940)).save('grid_right.png')
print('ok')
"
